def word_break(s: str, word_dict: list[str]) -> list[str]:
    n = len(s)
    word_set = set(word_dict)
    memo = {}

    def backtrack(start):
        if start == n:
            return ['']
        if start in memo:
            return memo[start]

        sentences = []
        for end in range(start + 1, n + 1):
            prefix = s[start:end]
            if prefix in word_set:
                for rest in backtrack(end):
                    sentences.append(prefix + ('' if not rest else ' ' + rest))

        memo[start] = sentences
        return sentences

    all_sentences = backtrack(0)
    all_sentences.sort()

    return all_sentences

# Example usage:
s = "catsanddog"
word_dict = ["cat", "cats", "and", "sand", "dog"]
print(word_break(s, word_dict))  # Expected output: ['cats and dog', 'cat sand dog']
